	/**
	 * Default Constructor
	 */
    public ChannelService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ChannelEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ChannelRepository.class) );
		this.validator		= applicationContext.getBean(ChannelValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Channel
	 */
		public Channel createChannel( CreateChannelCommand command ) {

		Channel entity = new Channel();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setChannelId( command.getChannelId() );
            entity.setName( command.getName() );
            entity.setChannelCode( command.getChannelCode() );
            entity.setLocale( command.getLocale() );
            entity.setDomain( command.getDomain() );
            entity.setAsActive( command.getAsActive() );
            entity.setDefaultCurrency( command.getDefaultCurrency() );
            entity.setChannelType( command.getChannelType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Channel {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateChannelCommand
	 * @return		Channel
	 */
	public Channel updateChannel( UpdateChannelCommand command ) {

		Channel entity = new Channel();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setChannelId( command.getChannelId() );
            entity.setName( command.getName() );
            entity.setChannelCode( command.getChannelCode() );
            entity.setLocale( command.getLocale() );
            entity.setDomain( command.getDomain() );
            entity.setAsActive( command.getAsActive() );
            entity.setDefaultCurrency( command.getDefaultCurrency() );
            entity.setMerchant( command.getMerchant() );
            entity.setCatalogs( command.getCatalogs() );
            entity.setPromotions( command.getPromotions() );
            entity.setShippingMethods( command.getShippingMethods() );
            entity.setPaymentProviders( command.getPaymentProviders() );
            entity.setChannelType( command.getChannelType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Channel {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteChannelCommand
	 */
	public void delete( DeleteChannelCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getChannelId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Channel {0} ", id );

	}

	/**
	 * Method to retrieve the Channel via ChannelFetchOneSummary
	 * @param 	summary ChannelFetchOneSummary
	 * @return 	ChannelFetchOneResponse
	 */
	public Channel getChannel( ChannelFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ChannelFetchOneSummary arg cannot be null" );

		Channel entity = null;
		UUID id = summary.getChannelId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Channel using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Channels
	 *
	 * @return 	List<Channel>
	 */
    public List<Channel> getAllChannel() {
		List<Channel> list = projector.findAll( new FindAllChannelQuery() );
		return list;
	}

	/**
	 * assign Merchant on Channel
	 * @param		command AssignMerchantToChannelCommand
	 */
	public void assignMerchant( AssignMerchantToChannelCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignMerchant(command.getChannelId(), command.getAssignment());

	}

